package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;import com.ruoyi.medical.contracts.*;import com.ruoyi.medical.identity.ApplicationSessionIdentity;import jakarta.servlet.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
/** Normal authenticated human preparation, not an executor-injected original or approval. */
@RestController @ConditionalOnProperty(prefix="medical.formal-evaluation-execution",name="enabled",havingValue="true")
public final class FormalEvaluationCaseOriginalControllerV2 {
 private final FormalEvaluationCaseAuthoring authoring;private final ApplicationSessionIdentity identities;private final FormalEvaluationCaseOriginals originals;private final FormalEvaluationStageInputSchema schema;
 public FormalEvaluationCaseOriginalControllerV2(ApplicationSessionIdentity identities,FormalEvaluationCaseOriginals originals,FormalEvaluationStageInputSchema schema,FormalEvaluationCaseAuthoring authoring){this.authoring=authoring;this.identities=identities;this.originals=originals;this.schema=schema;}
 @PostMapping(value="/api/v2/formal-evaluation-case-originals/author",consumes="application/json") public JsonNode author(HttpServletRequest request,HttpServletResponse response,Authentication auth)throws Exception{var context=FormalEvaluationInputHttp.headers(request,response,true,"2.0.0");return authoring.author(identities.requireCurrent(request,auth),context,body(request));}
 @PostMapping(value="/api/v2/formal-evaluation-case-originals",consumes="application/json") public JsonNode register(HttpServletRequest request,HttpServletResponse response,Authentication auth)throws Exception{var context=FormalEvaluationInputHttp.headers(request,response,true,"2.0.0");return originals.register(identities.requireCurrent(request,auth),context,body(request));}
 @PostMapping(value="/api/v2/formal-evaluation-case-originals/{registration}/approval",consumes="application/json") public JsonNode approve(HttpServletRequest request,HttpServletResponse response,Authentication auth,@PathVariable String registration)throws Exception{var context=FormalEvaluationInputHttp.headers(request,response,true,"2.0.0");return originals.approve(identities.requireCurrent(request,auth),context,registration,body(request));}
 @GetMapping("/api/v2/formal-evaluation-case-originals/{run}/steps/{step}") public JsonNode read(HttpServletRequest request,HttpServletResponse response,Authentication auth,@PathVariable String run,@PathVariable String step)throws Exception{var context=FormalEvaluationInputHttp.headers(request,response,false,"2.0.0");return StrictFieldWireVersion.response(originals.read(identities.requireCurrent(request,auth),context,run,step),"2.0.0","/case/schema_version");}
 private JsonNode body(HttpServletRequest request)throws Exception{if(request.getContentLengthLong()>2097152)throw new TenantAccessException(ErrorCode.FILE_TOO_LARGE);var raw=request.getInputStream().readNBytes(2097153);if(raw.length>2097152)throw new TenantAccessException(ErrorCode.FILE_TOO_LARGE);var value=schema.read(raw);if(!"2.0.0".equals(FormalEvaluationStageInputSchema.version(value)))throw new SchemaRejection(ErrorCode.SCHEMA_UNSUPPORTED);return value;}
 @ExceptionHandler(Exception.class)void failed(Exception failure,HttpServletResponse response)throws java.io.IOException{FormalEvaluationInputHttp.failure(failure,response);}
}
